class Solution:
    def sortedSquares(self, nums: List[int]) -> List[int]:
        n = len(nums)
        out = [0] * n
        l, r = 0, n - 1
        for i in range(n - 1, -1, -1):           # fill from the back with the largest square
            if abs(nums[l]) > abs(nums[r]):
                out[i] = nums[l] ** 2
                l += 1
            else:
                out[i] = nums[r] ** 2
                r -= 1
        return out
